import itertools
edges_fixed=[(2,8),(1,9),(0,6),(3,10),(0,9),(3,9)]
# try assign colors 0/1 to 12 vertices satisfying fixed edges opposite
n=12
for colors in itertools.product([0,1], repeat=n):
    ok=True
    for u,v in edges_fixed:
        if colors[u]==colors[v]:
            ok=False;break
    if ok:
        print('found')
        print(colors)
        break
